VALUES (1642, 'tt0113957', NULL, 'The Net', 'The Net', 'movie', 1995, 'https://image.tmdb.org/t/p/w500/dtupntUFMD5iXBo8HLfALt2ET4R.jpg', 'https://image.tmdb.org/t/p/original/dDE6EIaFsPFJPLXHG1ghuPQc7ST.jpg', 'Angela Bennett is a freelance computer systems analyst who tracks down software viruses. At night, she hooks up to the internet and chats to others ''surfing the net''. While de-bugging a new high-tech game for a cyber friend, she comes across a top secret program and becomes the target of a mysterious organization, who will stop at nothing to erase her identity and her existence in order to protect the project.', NULL, NULL, 3.9254, 6.059, 0, 1.02, '2026-11-20 13:26:55', '2026-11-20 13:26:55')
