VALUES (11232, 'tt0035423', NULL, 'Kate & Leopold', 'Kate & Leopold', 'movie', 2001, 'https://image.tmdb.org/t/p/w500/fbWYmlGvQXmmZEr4bMeJFjWfFXZ.jpg', 'https://image.tmdb.org/t/p/original/2nKFPGQDMMMW13zyLTmO2M7rMI3.jpg', 'When her scientist ex-boyfriend discovers a portal to travel through time -- and brings back a 19th-century nobleman named Leopold to prove it -- a skeptical Kate reluctantly takes responsibility for showing Leopold the 21st century. The more time Kate spends with Leopold, the harder she falls for him. But if he doesn''t return to his own time, his absence will forever alter history.', NULL, NULL, 3.0461, 6.4, 0, 1.01, '2026-11-20 13:26:55', '2026-11-20 13:26:55')
