VALUES (79257, 'tt0084359', NULL, 'Mother Lode', 'Mother Lode', 'movie', 1982, 'https://image.tmdb.org/t/p/w500/dyhxbM4lSQjb3jvvSIpiru4HmKz.jpg', 'https://image.tmdb.org/t/p/original/SEAaID8GLohvL2K3szh4S1ZJID.jpg', 'A couple of young adventurers go into the wilderness of British Columbia in search of a lost colleague. Their plane crashes and they find themselves at the mercy of a crazed old Scottish miner, who has lived in isolation for many decades searching the mountain caves for a chamber of long lost gold. He is prepared to do anything - including murder - to keep his gold for himself.', NULL, NULL, 1.2728, 5.7, 0, 1.02, '2026-11-20 13:26:55', '2026-11-20 13:26:55')
