VALUES (1748007, 'tt44146991', NULL, 'Niu Lai', '牛来', 'movie', 2026, 'https://image.tmdb.org/t/p/w500/eum2kcqFr665SgnFulgO7b2lRwW.jpg', 'https://image.tmdb.org/t/p/original/zByhNXeL7JpyNgLETSZipb8NKxr.jpg', 'The naive calf Niu Lai loves exploring the grasslands, but struggles to live up to his family’s expectations as future leader of the herd. With migration fast approaching, Niu Lai finds unlikely allies on his journey to learn the meaning of courage as they prepare for a dangerous trek across the desert.', NULL, NULL, 1.3295, 4.2, 0, 9.03, '2026-11-20 13:26:55', '2026-11-20 13:26:55')
