VALUES (302376, 'tt4076058', NULL, 'We Are Young. We Are Strong.', 'Wir sind jung. Wir sind stark.', 'movie', 2014, 'https://image.tmdb.org/t/p/w500/4x4AZaukJLCkHiY8p9UXyjNiH2U.jpg', 'https://image.tmdb.org/t/p/original/8mvYcUFJ20h2lKHKeBr2px824XW.jpg', 'On 24th August 1992 in the eastern German city of Rostock, a rampaging mob, to the applause and cheering of more than 3,000 bystanders, besieged and set fire to a residential building containing, among others, more than 120 Vietnamese men, women, and children on what has since become known as "The Night of the Fire." The riots became a symbol of xenophobia in the just-reunited Germany. This film recounts the incident from the perspectives of three very different characters.', NULL, NULL, 1.1845, 6.8, 0, 10.03, '2026-11-20 13:26:55', '2026-11-20 13:26:55')
