VALUES (775630, 'tt13696108', NULL, 'Cockroach', '曱甴', 'movie', 2020, 'https://image.tmdb.org/t/p/w500/eQzXPuuGBITNJKmFfGMkX5PO1qH.jpg', NULL, 'In February 2019, the Hong Kong government proposed a bill that would have allowed the extradition of criminal suspects from Hong Kong to face trial in mainland China. The controversial bill sparked immediate outrage over widespread fear of arbitrary detention and politically motivated trials that would decimate Hong Kong’s autonomy under ‘one country, two systems.’ Protests escalated into epic pro-democracy demonstrations, in part led by young people connected via social media. COCKROACH, filmed during the height of the protests, captures the extraordinary intensity of an unprecedented era in Hong Kong’s history.', NULL, NULL, 0.4399, 7.0, 0, 10.02, '2026-11-20 13:26:55', '2026-11-20 13:26:55')
