VALUES (837, 'tt0086541', NULL, 'Videodrome', 'Videodrome', 'movie', 1983, 'https://image.tmdb.org/t/p/w500/qqqkiZSU9EBGZ1KiDmfn07S7qvv.jpg', 'https://image.tmdb.org/t/p/original/eBS1nvaQ7BMdsSlkoLyKapf0FEY.jpg', 'As the president of a trashy TV channel, Max Renn is desperate for new programming to attract viewers. When he happens upon "Videodrome," a TV show dedicated to gratuitous torture and punishment, Max sees a potential hit and broadcasts the show on his channel. However, after his girlfriend auditions for the show and never returns, Max investigates the truth behind Videodrome and discovers that the graphic violence may not be as fake as he thought.', NULL, NULL, 6.5292, 7.248, 0, 5.98078181818181846e+01, '2026-07-15 12:01:52', '2026-11-20 13:26:55')
