VALUES (2112, 'tt0120784', NULL, 'Payback', 'Payback', 'movie', 1999, 'https://image.tmdb.org/t/p/w500/8Bqlv2kbOyZFqfiPNgzdBscqYPn.jpg', 'https://image.tmdb.org/t/p/original/fP9QYH8T9LBnsvnQvcqetB4nuwX.jpg', 'With friends like these, who needs enemies? That''s the question bad guy Porter is left asking after his wife and partner steal his heist money and leave him for dead -- or so they think. Five months and an endless reservoir of bitterness later, Porter''s partners and the crooked cops on his tail learn how bad payback can be.', NULL, NULL, 5.5475, 6.842, 0, 1.52036363636363631e+01, '2026-07-15 12:01:52', '2026-11-20 13:26:55')
