VALUES (1415, 'tt0320244', NULL, 'Party Monster', 'Party Monster', 'movie', 2003, 'https://image.tmdb.org/t/p/w500/4DVWGtV1OA3W8kZxiimdNsepS6O.jpg', 'https://image.tmdb.org/t/p/original/c0tjgU8rq9ZsveoCvlqOnJQ5Aji.jpg', 'The New York club scene of the 80s and 90s was a world like no other. Into this candy-colored, mirror ball playground stepped Michael Alig, a wannabe from nowhere special. Under the watchful eye of veteran club kid James St. James, Alig quickly rose to the top... and there was no place to go but down.', NULL, NULL, 1.4887, 5.814, 0, 5.0768571428571434e+01, '2026-07-15 12:01:52', '2026-11-20 13:26:55')
