VALUES (11933, 'tt0102558', NULL, 'Nothing but Trouble', 'Nothing but Trouble', 'movie', 1991, 'https://image.tmdb.org/t/p/w500/Apk5Hbby70diyeMHd2VhxUSHNW.jpg', 'https://image.tmdb.org/t/p/original/5Uo0vXeg7KDTDwodKy9FC5f5K8N.jpg', 'While attempting to seduce gorgeous lawyer Diane Lightson, wealthy gadabout Chris Thorne agrees to drive her to Atlantic City, N.J. But, when some reckless driving draws the attention of a deeply critical cop, they and the flamboyant "Brazillionaires" who tagged along end up in the court of a grotesque and vengeful judge, who has a special vendetta against the wealthy and erudite.', NULL, NULL, 2.4513, 5.286, 0, 1.50070000000000014e+01, '2026-07-20 04:02:06', '2026-11-20 13:26:55')
