VALUES (16871, 'tt1127180', NULL, 'Drag Me to Hell', 'Drag Me to Hell', 'movie', 2009, 'https://image.tmdb.org/t/p/w500/fdyejM5Zd6dsa0YyWa02ZAKwQzK.jpg', 'https://image.tmdb.org/t/p/original/3tvwsRSIDgwJuaGdh67XZ942UMy.jpg', 'After denying a woman the extension she needs to keep her home, loan officer Christine Brown sees her once-promising life take a startling turn for the worse. Christine is convinced she''s been cursed by a Gypsy, but her boyfriend is skeptical. Her only hope seems to lie in a psychic who claims he can help her lift the curse and keep her soul from being dragged straight to hell.', NULL, NULL, 5.052, 6.496, 0, 2.07152941176470584e+01, '2026-07-20 04:02:06', '2026-11-20 13:26:55')
