VALUES (11852, 'tt0302640', NULL, 'The Hot Chick', 'The Hot Chick', 'movie', 2002, 'https://image.tmdb.org/t/p/w500/lnnGE4TKa05t20SZ2batuAhXCp4.jpg', 'https://image.tmdb.org/t/p/original/vK8uTRjiNkJ7P2VINNLxYWiiw0z.jpg', 'Not only is Jessica Spencer the most popular girl in school -- she is also the meanest. But things change for the attractive teen when a freak accident involving a cursed pair of earrings and a chance encounter at a gas station causes her to switch bodies with Clive, a sleazy crook. Jessica, in the form of the repulsive Clive, struggles to adjust to this radical alteration and sets out to get her own body back before the upcoming prom.', NULL, NULL, 5.8386, 6.357, 0, 10.35, '2026-07-20 04:02:06', '2026-11-20 13:26:55')
