VALUES (16127, 'tt0080752', NULL, 'Forbidden Zone', 'Forbidden Zone', 'movie', 1982, 'https://image.tmdb.org/t/p/w500/z4lrDkJVkW2kQZnNcHtUQ38DDAb.jpg', 'https://image.tmdb.org/t/p/original/2m7URnwkBzXMRHvzb8SicI0x4rt.jpg', 'A mysterious door in the basement of the Hercules house leads to the Sixth Dimension by way of a gigantic set of intestine. When lovely exchange student Frenchy slips through the door, the diminuitive King Fausto falls in love with her. The jealous Queen Doris takes Frenchy prisoner, and it is up to the Hercules family and friend Squeezit Henderson to rescue her.', NULL, NULL, 1.3263, 6.174, 0, 21.02, '2026-07-21 03:32:24', '2026-11-20 13:26:55')
