VALUES (235201, 'tt1586677', NULL, 'I-Be Area', 'I-Be Area', 'movie', 2007, 'https://image.tmdb.org/t/p/w500/5UcbZvnpjqFDT85855GrIandi4P.jpg', 'https://image.tmdb.org/t/p/original/7FUdGHt3aU6CtYYUUgyEPoYXMqz.jpg', 'Dazzling and raucous, Ryan Trecartin''s first feature-length video takes cues from chat rooms, social networking web sites, YouTube, John Waters, and Pee-wee’s Playhouse, and then turns them upside down and inside out to create an entirely singular video genre. In I-BE AREA, Trecartin intertwines the stories of an incredible ensemble cast to follow a day in the life of I-BE II, the rebellious clone of I-BE.', NULL, NULL, 0.2295, 5.5, 0, 8.51666666666666571e+00, '2026-07-21 03:32:24', '2026-11-20 13:26:55')
