VALUES (320413, 'tt4381236', NULL, 'The Greasy Strangler', 'The Greasy Strangler', 'movie', 2016, 'https://image.tmdb.org/t/p/w500/lsIJ8iTA2DK12SNTKf0vLKh1BGm.jpg', 'https://image.tmdb.org/t/p/original/flz1hSZTUl5wNs2i4nmcyX8Tg7n.jpg', 'Ronnie runs a Disco walking tour with his son, Brayden. When a sexy woman takes the tour, it begins a competition between father and son for her love. It also signals the arrival of an oily strangler who stalks the streets at night.', NULL, NULL, 0.9353, 5.5, 0, 1.99693333333333313e+01, '2026-07-21 03:32:24', '2026-11-20 13:26:55')
