VALUES (8764, 'tt0088286', NULL, 'Top Secret!', 'Top Secret!', 'movie', 1984, 'https://image.tmdb.org/t/p/w500/hRTbfR27xghnVMs3ZJ3EhK3zzud.jpg', 'https://image.tmdb.org/t/p/original/ljY0REcQp0HyEjlfkYP4kopKsIR.jpg', 'Popular and dashing American singer Nick Rivers travels to East Germany to perform in a music festival. When he loses his heart to the gorgeous Hillary Flammond, he finds himself caught up in an underground resistance movement. Rivers joins forces with Agent Cedric and Flammond to attempt the rescue of her father, Dr. Paul, from the Germans, who have captured the scientist in hopes of coercing him into building a new naval mine.', NULL, NULL, 3.7991, 7.102, 0, 9.01571428571428512e+00, '2026-07-21 03:32:24', '2026-11-20 13:26:55')
