VALUES (580633, 'tt4522922', NULL, 'Tales from the Lodge', 'Tales from the Lodge', 'movie', 2019, 'https://image.tmdb.org/t/p/w500/mQUIAwsebsOEq7CR8KUfM8HP9ft.jpg', 'https://image.tmdb.org/t/p/original/lGEQgPswUFSTvJfb9WCfNSCTiFQ.jpg', 'Tales From The Lodge is a fresh take on the portmanteau horror-comedy genre. An isolated lodge somewhere in England. Five old university pals, now nudging 40, gather for a weekend to scatter the ashes of their friend, Jonesy, who drowned himself in the lake three years earlier. They settle in for a fun evening, entertaining each other with stories of murders, ghosts, zombies and possessions, but as day turns to night, the gang become aware of another horror story unfolding around them - And this one is real.', NULL, NULL, 1.3275, 5.4, 0, 3.03780769230769251e+01, '2026-07-21 03:32:24', '2026-11-20 13:26:55')
