VALUES (284054, 'tt1825683', NULL, 'Black Panther', 'Black Panther', 'movie', 2018, 'https://image.tmdb.org/t/p/w500/uxzzxijgPIY7slzFvMotPv8wjKA.jpg', 'https://image.tmdb.org/t/p/original/b6ZJZHUdMEFECvGiDpJjlfUWela.jpg', 'King T''Challa returns home to the reclusive, technologically advanced African nation of Wakanda to serve as his country''s new leader. However, T''Challa soon finds that he is challenged for the throne by factions within his own country as well as without. Using powers reserved to Wakandan kings, T''Challa assumes the Black Panther mantle to join with ex-girlfriend Nakia, the queen-mother, his princess-kid sister, members of the Dora Milaje (the Wakandan ''special forces'') and an American secret agent, to prevent Wakanda from being dragged into a world war.', NULL, NULL, 18.117, 7.358, 0, 9.40800000000000125e+00, '2026-08-08 02:23:49', '2026-11-20 13:26:55')
