VALUES (10660, 'tt0110167', NULL, 'It Could Happen to You', 'It Could Happen to You', 'movie', 1994, 'https://image.tmdb.org/t/p/w500/6UOaeLDOdwwTMQtbl5YL6EGjqy0.jpg', 'https://image.tmdb.org/t/p/original/rHqIKBrvmRTExmi7XN31OjRSPKT.jpg', 'Charlie Lang is a simple, kindhearted New York City cop. When he realizes he has no money to tip waitress Yvonne Biasi, Lang offers her half the winnings of his lottery ticket. Amazingly, the ticket happens to be a winner, in the sum of $4 million. True to his word, Lang proceeds to share the prize money with Biasi, which infuriates his greedy wife, Muriel. Not content with the arrangement, Muriel begins scheming to take all the money.', NULL, NULL, 3.9351, 6.7, 0, 3.02333333333333342e+00, '2026-08-08 02:23:49', '2026-11-20 13:26:55')
