VALUES (63492, 'tt0770703', NULL, 'What''s Your Number?', 'What''s Your Number?', 'movie', 2011, 'https://image.tmdb.org/t/p/w500/eqn3UeXMY9W1Ow3jIZ6COqbjUWX.jpg', 'https://image.tmdb.org/t/p/original/dN4L6qx63sly7SJki2YBXjGcnEy.jpg', 'Ally Darling is realizing she''s a little lost in life. Her latest romance has just fizzled out, and she''s just been fired from her marketing job. Then she reads an eye-opening magazine article that warns that 96 percent of women who''ve been with 20 or more lovers are unlikely to find a husband. Determined to turn her life around and prove the article wrong, Ally embarks on a mission to find the perfect mate from among her numerous ex-boyfriends.', NULL, NULL, 3.5493, 6.465, 0, 6.26, '2026-08-11 02:46:38', '2026-11-20 13:26:55')
